 if(session_status()!==PHP_SESSION_ACTIVE)session_start();$user=$_SESSION['user']??'';if(!$user||(isset($_SESSION['expire'])&&$_SESSION['expire']<time()))coResponse(401,['error'=>'Inicia sesión nuevamente.']);
 $_SESSION['accounting_csrf']=$_SESSION['accounting_csrf']??bin2hex(random_bytes(32));$csrf=$_SESSION['accounting_csrf'];session_write_close();
